class ShopableVideoSticky extends HTMLElement{constructor(){super(),this.miniVideo=this.querySelector(".mini-video__video"),this.closeButton=this.querySelector(".close-mini-video"),this.isVisible=!1,this.scrollThreshold=300,this.actionClose="true"===this.getAttribute("data-action-close"),this.cookieName="video_sticky_closed",this.init()}init(){this.setupEventListeners(),this.actionClose&&this.checkClosedCookie()||this.handleScroll()}setupEventListeners(){window.addEventListener("scroll",this.handleScroll.bind(this)),this.closeButton&&this.closeButton.addEventListener("click",()=>{this.hideVideo(),this.actionClose&&this.setClosedCookie()})}handleScroll(){window.scrollY>this.scrollThreshold&&!this.checkClosedCookie()&&this.showVideo()}showVideo(){!this.isVisible&&this.miniVideo&&(this.miniVideo.classList.add("is-visible"),this.isVisible=!0)}hideVideo(){this.isVisible&&this.miniVideo&&(this.miniVideo.classList.remove("is-visible"),this.isVisible=!1)}setClosedCookie(){const i=new Date;i.setTime(i.getTime()+864e5),document.cookie=`${this.cookieName}=true; expires=${i.toUTCString()}; path=/; SameSite=Lax`}checkClosedCookie(){const i=document.cookie.split(";");for(let e=0;e<i.length;e++){const s=i[e].trim();if(0===s.indexOf(`${this.cookieName}=`))return"true"===s.substring(this.cookieName.length+1)}return!1}}customElements.define("shopable-video-sticky",ShopableVideoSticky);